export class AppError extends Error {
  constructor(public readonly status: number, message: string, public readonly code: string) {
    super(message);
  }
}

export class UnauthorizedError extends AppError {
  constructor(message = "Authentication required") { super(401, message, "UNAUTHORIZED"); }
}
export class ForbiddenError extends AppError {
  constructor(message = "Forbidden") { super(403, message, "FORBIDDEN"); }
}
export class NotFoundError extends AppError {
  constructor(message = "Resource not found") { super(404, message, "NOT_FOUND"); }
}
export class ConflictError extends AppError {
  constructor(message = "Conflict") { super(409, message, "CONFLICT"); }
}

import type { ErrorRequestHandler } from "express";
import { AppError } from "../shared/errors.js";
import { env } from "../config/env.js";

export const errorHandler: ErrorRequestHandler = (err, _req, res, next) => {
  if (res.headersSent) return next(err);
  if (err instanceof AppError) {
    return res.status(err.status).json({ error: { code: err.code, message: err.message } });
  }
  if (env.NODE_ENV !== "production") console.error(err);
  return res.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Internal server error" } });
};

import type { RequestHandler } from "express";
import jwt from "jsonwebtoken";
import { env } from "../config/env.js";
import { UnauthorizedError } from "../shared/errors.js";

declare global {
  namespace Express { interface Request { user?: { id: string; email: string }; } }
}

export const authenticate: RequestHandler = (req, _res, next) => {
  const header = req.header("authorization");
  if (!header?.startsWith("Bearer ")) return next(new UnauthorizedError());
  try {
    const payload = jwt.verify(header.slice(7), env.JWT_SECRET);
    if (typeof payload !== "object" || typeof payload.sub !== "string" || typeof payload.email !== "string") {
      return next(new UnauthorizedError("Invalid access token"));
    }
    req.user = { id: payload.sub, email: payload.email };
    return next();
  } catch { return next(new UnauthorizedError("Invalid access token")); }
};

