import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import { pool } from "../../db/pool.js";
import { env } from "../../config/env.js";
import { ConflictError, UnauthorizedError } from "../../shared/errors.js";

export async function register(email: string, password: string) {
  const hash = await bcrypt.hash(password, 12);
  try {
    const result = await pool.query(
      "INSERT INTO users(email, password_hash) VALUES ($1,$2) RETURNING id, email, created_at",
      [email, hash]
    );
    return result.rows[0];
  } catch (error: any) {
    if (error?.code === "23505") throw new ConflictError("Email is already registered");
    throw error;
  }
}

export async function login(email: string, password: string) {
  const result = await pool.query("SELECT id, email, password_hash FROM users WHERE email = $1", [email]);
  if (result.rowCount !== 1) throw new UnauthorizedError("Invalid credentials");
  const user = result.rows[0];
  const valid = await bcrypt.compare(password, user.password_hash);
  if (!valid) throw new UnauthorizedError("Invalid credentials");
  const token = jwt.sign({ email: user.email }, env.JWT_SECRET, { subject: user.id, expiresIn: env.JWT_EXPIRES_IN as jwt.SignOptions["expiresIn"] });
  return { accessToken: token, user: { id: user.id, email: user.email } };
}

