import { pool } from "../../db/pool.js";
import { ConflictError } from "../../shared/errors.js";

export async function createProject(userId: string, name: string, key: string) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const project = await client.query(
      "INSERT INTO projects(name, key, created_by) VALUES ($1,$2,$3) RETURNING id, name, key, created_at",
      [name, key, userId]
    );
    await client.query(
      "INSERT INTO project_members(project_id, user_id, role) VALUES ($1,$2,'OWNER')",
      [project.rows[0].id, userId]
    );
    await client.query("COMMIT");
    return project.rows[0];
  } catch (error: any) {
    await client.query("ROLLBACK");
    if (error?.code === "23505") throw new ConflictError("Project key already exists");
    throw error;
  } finally { client.release(); }
}

export async function getMembership(projectId: string, userId: string) {
  const result = await pool.query(
    "SELECT role FROM project_members WHERE project_id = $1 AND user_id = $2",
    [projectId, userId]
  );
  return result.rows[0] as { role: string } | undefined;
}

