import { pool } from "../../db/pool.js";

const sortColumns = { createdAt: "created_at", priority: "priority" } as const;

export async function createIssue(projectId: string, userId: string, input: { title: string; description: string; status: string; priority: string }) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const issue = await client.query(
      "INSERT INTO issues(project_id,title,description,status,priority,created_by) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id, project_id, title, description, status, priority, created_at, updated_at",
      [projectId, input.title, input.description, input.status, input.priority, userId]
    );
    await client.query(
      "INSERT INTO audit_events(actor_id,action,entity_type,entity_id) VALUES ($1,'issue.created','issue',$2)",
      [userId, issue.rows[0].id]
    );
    await client.query("COMMIT");
    return issue.rows[0];
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally { client.release(); }
}

export async function listIssues(projectId: string, input: { page: number; pageSize: number; status?: string; sortBy: keyof typeof sortColumns; direction: "asc"|"desc" }) {
  const column = sortColumns[input.sortBy];
  const direction = input.direction === "asc" ? "ASC" : "DESC";
  const offset = (input.page - 1) * input.pageSize;
  const values: unknown[] = [projectId];
  let where = "WHERE project_id = $1";
  if (input.status) { values.push(input.status); where += ` AND status = $${values.length}`; }
  values.push(input.pageSize, offset);
  const result = await pool.query(
    `SELECT id, project_id, title, description, status, priority, created_at, updated_at FROM issues ${where} ORDER BY ${column} ${direction}, id ASC LIMIT $${values.length - 1} OFFSET $${values.length}` ,
    values
  );
  return result.rows;
}

import { ForbiddenError } from "../../shared/errors.js";
import { getMembership } from "../projects/project.service.js";
import { createIssue, listIssues } from "./issue.repository.js";

async function assertMember(userId: string, projectId: string, write = false) {
  const membership = await getMembership(projectId, userId);
  if (!membership) throw new ForbiddenError("You are not a member of this project");
  if (write && !["OWNER", "MAINTAINER"].includes(membership.role)) {
    throw new ForbiddenError("You are not allowed to modify this project");
  }
}

export async function createProjectIssue(userId: string, projectId: string, input: { title: string; description: string; status: string; priority: string }) {
  await assertMember(userId, projectId, true);
  return createIssue(projectId, userId, input);
}

export async function getProjectIssues(userId: string, projectId: string, input: { page: number; pageSize: number; status?: string; sortBy: "createdAt"|"priority"; direction: "asc"|"desc" }) {
  await assertMember(userId, projectId);
  return listIssues(projectId, input);
}

